const float scroll = 2.0;
bool cactus( vec2 pos ) {
    bool match = false;

    float X = floor( (5.0*pos.x - 2.0*pos.y + 7.0) / 18.0 );
    float Y = floor( (4.0*pos.y - pos.x + 4.0)/18.0 );

    float[] a = float[](1.5, 1.5, 0.5, 1.5, 2.5, 2.5);
    float[] b = float[](0.5, 1.5, 2.5, 2.5, 2.5, 3.5);

    for (int i = 0; i<6; i++) {
        if (abs(pos.x - 4.0*X - 2.0*Y - a[i]) <= 0.5 && abs(pos.y - X - 5.0*Y - b[i]) <= 0.5) {
        return true;
        break;
        }
    }
    return false;
}

const float res = 15.0;
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/min( iResolution.x, iResolution.y )*res+iTime*scroll; // normalized coordinates

    vec3 col = vec3(0.62, 1.0, 0.6);
    if (cactus(uv)) {
        col = vec3(0.94, 0.87, 0.44);
    } else {
        if (cactus(uv+vec2(2.0))) {
            col = vec3(0.3, 0.68, 0.14);
        }
    }

    fragColor = vec4(vec3(col), 1.0);
}
